            .output
            .as_ref()
            .and_then(|(cells, proofs)| parse_cells_and_proofs(cells, proofs).ok())
            .map(|(cells, proofs)| (cells.try_into().unwrap(), proofs.try_into().unwrap()));

        compare_result::<CellsAndKzgProofs, _>(&result, &expected)
    }
}

